import{_ as A,C as t,o as l,c as d,a3 as s,E as i,j as e,a as r,b as c,w as n,a6 as B}from"./chunks/framework.Ba39LDvt.js";const C=JSON.parse('{"title":"AI 芯片与新型计算","description":"认识上科大的智能计算系统、低比特与随机计算、类脑和光计算研究。","frontmatter":{"title":"AI 芯片与新型计算","description":"认识上科大的智能计算系统、低比特与随机计算、类脑和光计算研究。"},"headers":[],"relativePath":"research/ai-hardware.md","filePath":"research/ai-hardware.md","lastUpdated":1795525517000}'),u={name:"research/ai-hardware.md"};function f(m,a,p,b,g,_){const h=t("FacultyList"),o=t("CourseTable"),E=t("Mermaid");return l(),d("div",null,[a[1]||(a[1]=s('<h1 id="ai-芯片与新型计算" tabindex="-1">AI 芯片与新型计算 <a class="header-anchor" href="#ai-芯片与新型计算" aria-label="Permalink to &quot;AI 芯片与新型计算&quot;">​</a></h1><h2 id="这个方向在做什么" tabindex="-1">这个方向在做什么 <a class="header-anchor" href="#这个方向在做什么" aria-label="Permalink to &quot;这个方向在做什么&quot;">​</a></h2><p>AI 芯片研究如何让机器学习模型在真实硬件上高效运行。它不仅是增加乘加单元，还要组织数据搬运、片上存储、调度和软件接口；新型计算则进一步探索不同于常规高精度数字运算的表示与物理实现，例如低比特计算、随机计算、类脑计算和光计算。这些路线有不同误差来源与适用范围，不能仅凭理论运算次数直接比较优劣。</p><p>核心研究问题包括：</p><ul><li>怎样根据模型的数据依赖选择并行度、数据流与存储层级？</li><li>低比特量化与近似运算怎样影响任务精度和训练稳定性？</li><li>访存、数据转换、通信与控制会消耗多少系统能量？</li><li>新型器件的非理想性、随机性和漂移怎样进入计算模型？</li><li>硬件、编译器、运行时与算法怎样协同，而非各自优化局部指标？</li><li>面对不同批量、模型和输入规模，吞吐、延迟与能效能否保持？</li></ul><h2 id="上科大谁在做" tabindex="-1">上科大谁在做 <a class="header-anchor" href="#上科大谁在做" aria-label="Permalink to &quot;上科大谁在做&quot;">​</a></h2><p>上科大公开方向包含多种计算路线。刘思廷的先进计算电路与系统实验室（CAS4ET）关注动态随机计算、低比特计算与边缘 AI；中心材料介绍了基于单比特的先进计算系统及其潜在应用。娄鑫的 VSPLab 从智能视觉、三维重建与渲染芯片切入专用计算，哈亚军则研究 FPGA、超低功耗数字系统以及智能车等定制计算平台。</p><p>器件与光学侧，祝智峰研究基于自旋电子的磁存储与类脑计算；王成关注人工智能光计算芯片，曲俞睿关注光计算、光芯片与光子智能感知。它们说明“AI 硬件”并非单一技术栈：数字系统、磁性器件与光学系统需要不同知识和验证条件，应阅读各团队近期公开论文后再选择切入点。</p>',8)),i(h,{dir:"ai-hw"}),a[2]||(a[2]=e("h2",{id:"相关上科大课程",tabindex:"-1"},[r("相关上科大课程 "),e("a",{class:"header-anchor",href:"#相关上科大课程","aria-label":'Permalink to "相关上科大课程"'},"​")],-1)),a[3]||(a[3]=e("p",null,[e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/courses/ee219"},"EE219 智能计算系统"),r(" 是连接算法、电路与系统的直接入口；计划中的先修说明涉及数学、EE113、编程与 HDL 基础，不宜跳过数字实现能力的积累。")],-1)),i(o,{codes:"EE113,CS110,EE219,CS280,CS290U,CS290W,SI362,SI365"}),a[4]||(a[4]=e("p",null,[e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/courses/cs290u"},"CS290U"),r(" 可作为了解深度学习工程实践的课程入口；光计算、AI 部署与 AI 赋能芯片设计属于相邻但不同的主题，具体内容以当学期大纲为准。")],-1)),a[5]||(a[5]=e("h2",{id:"知识前置",tabindex:"-1"},[r("知识前置 "),e("a",{class:"header-anchor",href:"#知识前置","aria-label":'Permalink to "知识前置"'},"​")],-1)),a[6]||(a[6]=e("p",null,"下图是建议的学习依赖，不是正式先修表；硬件系统与模型算法两条线最终需要汇合。",-1)),(l(),c(B,null,{default:n(()=>[i(E,{id:"mermaid-72",class:"mermaid",graph:"graph%20TD%0A%20%20A%5B%22CS100%20%E8%AE%A1%E7%AE%97%E6%9C%BA%E7%BC%96%E7%A8%8B%22%5D%20--%3E%20B%5B%22CS110%20%E8%AE%A1%E7%AE%97%E6%9C%BA%E4%BD%93%E7%B3%BB%E7%BB%93%E6%9E%84I%22%5D%0A%20%20C%5B%22EE115B%20%E6%95%B0%E5%AD%97%E7%94%B5%E8%B7%AF%22%5D%20--%3E%20D%5B%22EE113%20%E6%95%B0%E5%AD%97%E9%9B%86%E6%88%90%E7%94%B5%E8%B7%AFI%22%5D%0A%20%20E%5B%22%E7%BA%BF%E6%80%A7%E4%BB%A3%E6%95%B0%E4%B8%8E%E6%A6%82%E7%8E%87%E5%9F%BA%E7%A1%80%22%5D%20--%3E%20F%5B%22%E6%9C%BA%E5%99%A8%E5%AD%A6%E4%B9%A0%E5%9F%BA%E7%A1%80%22%5D%0A%20%20F%20--%3E%20G%5B%22CS280%20%E6%B7%B1%E5%BA%A6%E5%AD%A6%E4%B9%A0%22%5D%0A%20%20A%20--%3E%20G%0A%20%20B%20--%3E%20H%5B%22EE219%20%E6%99%BA%E8%83%BD%E8%AE%A1%E7%AE%97%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20D%20--%3E%20H%0A%20%20G%20--%3E%20H%0A%20%20G%20--%3E%20I%5B%22CS290U%20%E6%B7%B1%E5%BA%A6%E5%AD%A6%E4%B9%A0%E5%B7%A5%E7%A8%8B%E5%AE%9E%E8%B7%B5%22%5D%0A%20%20H%20--%3E%20J%5B%22AI%20%E8%8A%AF%E7%89%87%E4%B8%8E%E6%96%B0%E5%9E%8B%E8%AE%A1%E7%AE%97%E7%A0%94%E7%A9%B6%22%5D%0A%20%20I%20--%3E%20J%0A%20%20K%5B%22%E5%99%A8%E4%BB%B6%E6%88%96%E5%85%89%E5%AD%A6%E5%9F%BA%E7%A1%80%22%5D%20--%3E%20J%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<h2 id="领域地图" tabindex="-1">领域地图 <a class="header-anchor" href="#领域地图" aria-label="Permalink to &quot;领域地图&quot;">​</a></h2><ul><li><strong>研究机构</strong>：MIT、Stanford、Berkeley，以及清华、复旦和中科院计算所的相关团队，覆盖加速器、存储与软硬协同等不同层级；类脑与光计算还需沿器件及光学文献扩展。</li><li><strong>产业参照</strong>：NVIDIA、AMD、Google TPU、华为昇腾等提供不同的计算系统实例；产品生态不能直接当成某种学术路线已获验证的证据，也不是本校合作名单。</li><li><strong>会议与期刊</strong>：ISCA、MICRO、HPCA、ASPLOS 偏架构与系统；ISSCC、VLSI Symposium、JSSC 偏电路和芯片；DAC、ICCAD 涉及设计方法。新型器件工作还可能出现在 IEDM 或 Nature Electronics。</li></ul><p>比较论文必须统一任务精度、模型、批量、工艺和计时范围。峰值 TOPS 不是应用吞吐率，计算阵列的理论能效也不等于含访存与转换开销的端到端能效。</p><h2 id="入门资源" tabindex="-1">入门资源 <a class="header-anchor" href="#入门资源" aria-label="Permalink to &quot;入门资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/ai-hardware">AI 硬件自学</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/architecture">体系结构自学</a>：建立模型、映射和硬件系统的共同语言。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/digital">数字自学</a>：补 HDL、验证和实现基础。</li><li><a href="https://www.mlsysbook.ai/" target="_blank" rel="noreferrer">MLSys Book</a>：从机器学习系统角度组织部署与硬件知识。</li><li><a href="https://mlcommons.org/" target="_blank" rel="noreferrer">MLCommons</a>：理解标准化性能评测关注的工作负载、精度与规则。</li></ul><p>入门可以先分析一个小型矩阵乘或卷积：记录数据移动量、运算量与瓶颈，再做一种可解释的优化。先复现功能与基线，不要只报告最有利输入上的速度。</p><h2 id="社区经验征集" tabindex="-1">社区经验征集 <a class="header-anchor" href="#社区经验征集" aria-label="Permalink to &quot;社区经验征集&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎相关课题组同学通过 <a href="/shanghaitech-ic-wiki-dev.github.io/about/contribute">参与共建</a> 补充“组里在做什么”、公开模型与硬件实践入口、进组准备建议；性能结论请说明平台、精度和测量边界。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/liust/main.htm" target="_blank" rel="noreferrer">刘思廷学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/louxin/main.htm" target="_blank" rel="noreferrer">娄鑫学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/hayj/main.htm" target="_blank" rel="noreferrer">哈亚军学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/zhuzhf/main.htm" target="_blank" rel="noreferrer">祝智峰学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/wangcheng1/main.htm" target="_blank" rel="noreferrer">王成学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/quyr/main.htm" target="_blank" rel="noreferrer">曲俞睿学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/_upload/article/files/d0/82/218152ad4bd29c54d8a89d0e6be7/2cba84cd-d335-4a72-8f17-68175bed8e69.pdf" target="_blank" rel="noreferrer">后摩尔中心介绍材料</a>：约 2024 年方向介绍。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年 SIST 开课计划</a>：实际课程与先修要求以最新公布为准。</li></ul>',10))])}const k=A(u,[["render",f]]);export{C as __pageData,k as default};
